# -*- coding: utf-8 -*-import sysimport timeimport tkinter as tk# --- Переменные графики ---font_size = 22  # Крупный шрифтdef update_time():    current_time = time.strftime('%H:%M:%S')    label.config(text=current_time)    root.after(1000, update_time)# Регулировка размера колесиком мышиdef change_font_size(event):    global font_size    if event.delta > 0 or event.num == 4:        font_size += 2    elif (event.delta < 0 or event.num == 5) and font_size > 10:        font_size -= 2    label.config(font=('Consolas', font_size, 'bold'))# Перетаскивание мышкой (Drag & Drop)def start_move(event):    root.x = event.x    root.y = event.ydef do_move(event):    x = root.winfo_x() + (event.x - root.x)    y = root.winfo_y() + (event.y - root.y)    root.geometry(f"+{x}+{y}")root = tk.Tk()root.overrideredirect(True)root.attributes('-topmost', True)root.attributes('-alpha', 0.8)root.configure(bg='#1e1e1e')label = tk.Label(    root,     font=('Consolas', font_size, 'bold'),     fg='#ffffff',     bg='#1e1e1e',    padx=12,    pady=6)label.pack()# Стартовые координаты (вверху слева)root.geometry('+50+50')# События мыши:# Перетаскивание зажатой ЛКМlabel.bind('<Button-1>', start_move)label.bind('<B1-Motion>', do_move)# Изменение размера колесикомlabel.bind('<MouseWheel>', change_font_size)# Закрытие ПКМ или Esclabel.bind('<Button-3>', lambda e: sys.exit())root.bind('<Escape>', lambda e: sys.exit())update_time()root.mainloop()